async (page) => {
  let n = 0;
  for (let i = 0; i < 100; i++) {
    const found = await page.evaluate(async () => {
      const g = document.querySelector('vaadin-grid');
      for (let top = 0; top <= g.scrollHeight; top += 200) {
        g.scrollToIndex(Math.floor(top/33));
        await new Promise(r => setTimeout(r, 150));
        const rows = [...g.shadowRoot.querySelectorAll('tr')].filter(r=>r.querySelector('td'));
        for (const r of rows) {
          const t = [...r.querySelectorAll('td')].map(c=>c.innerText.trim());
          if (t[3]==='Closed (lost)' && t[4]==="Linens 'n Things Inc.") { return t[2]; }
        }
      }
      return null;
    });
    if (!found) break;
    await page.getByText(found, {exact:true}).click();
    await page.getByRole('button', { name: 'Delete' }).click();
    await page.waitForTimeout(500);
    n++;
  }
  return n;
}

