async () => {
  const g = document.querySelector('vaadin-grid'); const seen = {};
  const total = g.scrollHeight/33+5;
  for (let idx=0; idx<=total; idx+=5){ g.scrollToIndex(idx); await new Promise(r=>setTimeout(r,200));
    for (const tr of g.shadowRoot.querySelectorAll('tbody tr')){ const t=[...tr.querySelectorAll('td slot')].map(s=>s.assignedNodes()[0]?.innerText?.trim()); if(t[2]) seen[t[2]]=t[3]+' | '+t[4]; } }
  const all=Object.entries(seen); return {count:all.length, linens:all.filter(e=>e[1].includes('Linens'))};
}

